# -*- coding: utf-8 -*-
"""
PR Reviewer Agent for Claude Code.
Analyzes PR diffs for security, architecture, and code quality.
"""

import re
import sys
import argparse
import json
import os
import subprocess
from typing import List, Dict, Any, Optional

class PRReviewer:
    """Agent that performs automated code review on git diffs."""

    DEFAULT_REPORT_TEMPLATE = """# PR Review Report

## 📊 Summary
{summary}

## 🛡️ Security Vulnerabilities
{security_findings}

## 🏗️ Architectural Risks
{architectural_findings}

## 💎 Code Quality & Consistency
{quality_findings}

---
*Generated by Claude Code PR Reviewer Agent v1.0*
"""

    def __init__(self, diff_content: str, config_path: Optional[str] = None):
        self.diff_content = diff_content
        self.config = self._load_config(config_path)
        self.findings = {
            "security": [],
            "architecture": [],
            "quality": []
        }

    def _load_config(self, config_path: Optional[str]) -> Dict[str, Any]:
        if config_path and os.path.exists(config_path):
            with open(config_path, "r", encoding="utf-8") as f:
                return json.load(f)

        # Fallback to local config if it exists
        local_config = os.path.join(os.path.dirname(__file__), "reviewer_config.json")
        if os.path.exists(local_config):
            with open(local_config, "r", encoding="utf-8") as f:
                return json.load(f)

        return {"security": {"patterns": {}}, "quality": {"patterns": {}}}

    def analyze(self) -> str:
        """Analyze the diff and return a markdown report."""
        if not self.diff_content.strip():
            return "# PR Review Report\n\n_No changes detected._"

        files = self._split_diff_by_file()

        for filename, content in files.items():
            self._analyze_file(filename, content)

        return self._generate_report()

    def _split_diff_by_file(self) -> Dict[str, str]:
        """Split a unified diff into per-file contents."""
        files = {}
        current_file = None
        current_lines = []

        for line in self.diff_content.splitlines():
            if line.startswith("diff --git"):
                if current_file:
                    files[current_file] = "\n".join(current_lines)
                # Parse filename from 'diff --git a/file b/file'
                parts = line.split(" ")
                if len(parts) >= 4:
                    current_file = parts[3][2:] if parts[3].startswith("b/") else parts[3]
                else:
                    current_file = "unknown"
                current_lines = [line]
            elif current_file:
                current_lines.append(line)

        if current_file:
            files[current_file] = "\n".join(current_lines)

        return files

    def _analyze_file(self, filename: str, content: str):
        """Perform analysis on a single file's diff."""
        lines = content.splitlines()

        # Track line numbers in the new version of the file
        current_new_line = 0

        for line in lines:
            if line.startswith("@@"):
                # Parse hunk header: @@ -start,len +start,len @@
                match = re.search(r"\+(\d+)", line)
                if match:
                    current_new_line = int(match.group(1)) - 1
                continue

            if line.startswith(" "):
                current_new_line += 1
                continue

            if line.startswith("+") and not line.startswith("+++"):
                current_new_line += 1
                # This is an added/modified line
                stripped_line = line[1:]

                # Security Patterns
                for name, rule in self.config.get("security", {}).get("patterns", {}).items():
                    if re.search(rule["regex"], stripped_line):
                        severity = rule.get("severity", "UNKNOWN")
                        self.findings["security"].append(
                            f"- **[{severity}] {name}** in `{filename}:{current_new_line}`: {rule['message']}"
                        )

                # Quality Patterns
                for name, rule in self.config.get("quality", {}).get("patterns", {}).items():
                    if re.search(rule["regex"], stripped_line):
                        severity = rule.get("severity", "UNKNOWN")
                        self.findings["quality"].append(
                            f"- **[{severity}] {name}** in `{filename}:{current_new_line}`: {rule['message']}"
                        )

                # Custom logic for Architectural Risks
                self._check_architectural_risks(filename, stripped_line, current_new_line)

    def _check_architectural_risks(self, filename: str, line: str, line_no: int):
        """Heuristics for architectural risks."""
        # Example: Business logic in views (simplified check)
        if "resources/views" in filename and ("DB::" in line or "app(" in line):
            self.findings["architecture"].append(
                f"- **Leakage of Concerns**: Possible business logic/DB call detected in view `{filename}:{line_no}`."
            )

        # Example: Deep nesting in Python
        if filename.endswith(".py") and line.startswith(" " * 16):
            self.findings["architecture"].append(
                f"- **High Cognitive Complexity**: Deeply nested code detected in `{filename}:{line_no}`."
            )

    def _generate_report(self) -> str:
        """Format findings into the final markdown report."""
        def format_section(key):
            return "\n".join(self.findings[key]) if self.findings[key] else "_No issues found._"

        total_issues = sum(len(v) for v in self.findings.values())
        summary = f"Detected {total_issues} potential issues across the changes."

        return self.DEFAULT_REPORT_TEMPLATE.format(
            summary=summary,
            security_findings=format_section("security"),
            architectural_findings=format_section("architecture"),
            quality_findings=format_section("quality")
        )

def get_git_diff(revision_range: Optional[str] = None) -> str:
    """Execute git diff and return the output."""
    cmd = ["git", "diff"]
    if revision_range:
        cmd.append(revision_range)

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        print(f"Error running git diff: {e.stderr}")
        sys.exit(1)

def main():
    if sys.platform == "win32":
        import io
        sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

    parser = argparse.ArgumentParser(description="Analyze PR diffs for quality and security.")
    parser.add_argument("file", nargs="?", help="Path to the diff file (stdin if omitted)")
    parser.add_argument("--diff", help="Git revision range (e.g. main...HEAD or HEAD~1)")
    parser.add_argument("--config", help="Path to custom config JSON")
    args = parser.parse_args()

    diff_text = ""
    if args.diff:
        diff_text = get_git_diff(args.diff)
    elif args.file:
        with open(args.file, "r", encoding="utf-8") as f:
            diff_text = f.read()
    else:
        if not sys.stdin.isatty():
            diff_text = sys.stdin.read()

    if not diff_text:
        parser.print_help()
        sys.exit(0)

    reviewer = PRReviewer(diff_text, args.config)
    report = reviewer.analyze()
    print(report)

if __name__ == "__main__":
    main()
